-- B7 review package only: execution requires the matching explicit approval.
-- On a completed schema-2 source/restore. Every violation count must be zero.
SELECT 'Dataset.datasetIdFormat' AS ruleName,COUNT(*) AS violations FROM Dataset WHERE NOT (id REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
SELECT 'Dataset.datasetCreatedAt' AS ruleName,COUNT(*) AS violations FROM Dataset WHERE NOT (createdAt > 0);
SELECT 'taskDataset' AS ruleName,COUNT(*) AS violations FROM Task c LEFT JOIN Dataset p ON c.datasetId=p.id WHERE c.datasetId IS NOT NULL AND p.id IS NULL;
SELECT 'taskObjectiveScope' AS ruleName,COUNT(*) AS violations FROM Task c LEFT JOIN Objective p ON c.datasetId=p.datasetId AND c.objectiveId=p.id WHERE c.datasetId IS NOT NULL AND c.objectiveId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'taskDirectProjectScope' AS ruleName,COUNT(*) AS violations FROM Task c LEFT JOIN Project p ON c.datasetId=p.datasetId AND c.directProjectId=p.id WHERE c.datasetId IS NOT NULL AND c.directProjectId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'Task.taskIdFormat' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT (id REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
SELECT 'Task.taskTitle' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT (OCTET_LENGTH(title) BETWEEN 1 AND 1024 AND CHAR_LENGTH(TRIM(title)) > 0);
SELECT 'Task.taskNotes' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT (notes IS NULL OR OCTET_LENGTH(notes) <= 65535);
SELECT 'Task.taskLifecycle' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT ((lifecycleStatus = 'active' AND completedAt IS NULL) OR (lifecycleStatus = 'completed' AND completedAt IS NOT NULL));
SELECT 'Task.taskTimes' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT (createdAt > 0 AND updatedAt >= createdAt AND (completedAt IS NULL OR completedAt BETWEEN createdAt AND updatedAt) AND (deletedAt IS NULL OR deletedAt BETWEEN createdAt AND updatedAt));
SELECT 'Task.taskRevision' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT (localRevision > 0);
SELECT 'Task.taskOwnerChoice' AS ruleName,COUNT(*) AS violations FROM Task WHERE NOT ((objectiveId IS NOT NULL) + (directProjectId IS NOT NULL) <= 1);
SELECT 'commandTaskV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord c LEFT JOIN Task p ON c.datasetId=p.datasetId AND c.taskId=p.id WHERE c.datasetId IS NOT NULL AND c.taskId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'commandPillarV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord c LEFT JOIN Pillar p ON c.datasetId=p.datasetId AND c.pillarId=p.id WHERE c.datasetId IS NOT NULL AND c.pillarId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'commandProjectV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord c LEFT JOIN Project p ON c.datasetId=p.datasetId AND c.projectId=p.id WHERE c.datasetId IS NOT NULL AND c.projectId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'commandObjectiveV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord c LEFT JOIN Objective p ON c.datasetId=p.datasetId AND c.objectiveId=p.id WHERE c.datasetId IS NOT NULL AND c.objectiveId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'CommandRecord.commandTargetV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord WHERE NOT ((taskId IS NOT NULL) + (pillarId IS NOT NULL) + (projectId IS NOT NULL) + (objectiveId IS NOT NULL) = 1);
SELECT 'CommandRecord.commandPayloadV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord WHERE NOT ((payloadVersion = 1 AND taskId IS NOT NULL OR payloadVersion = 2) AND resultingRevision > 0 AND JSON_VALID(afterSnapshot) AND (beforeSnapshot IS NULL OR JSON_VALID(beforeSnapshot)));
SELECT 'CommandRecord.commandKindV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord WHERE NOT (commandType IN ('create', 'edit', 'move', 'archive', 'restore', 'complete', 'reopen', 'undo', 'redo'));
SELECT 'CommandRecord.commandLifecycleTargetV2' AS ruleName,COUNT(*) AS violations FROM CommandRecord WHERE NOT (commandType NOT IN ('complete', 'reopen') OR taskId IS NOT NULL);
SELECT 'changeCommand' AS ruleName,COUNT(*) AS violations FROM LocalChange c LEFT JOIN CommandRecord p ON c.operationId=p.operationId WHERE c.operationId IS NOT NULL AND p.operationId IS NULL;
SELECT 'changeTaskV2' AS ruleName,COUNT(*) AS violations FROM LocalChange c LEFT JOIN Task p ON c.datasetId=p.datasetId AND c.taskId=p.id WHERE c.datasetId IS NOT NULL AND c.taskId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'changePillarV2' AS ruleName,COUNT(*) AS violations FROM LocalChange c LEFT JOIN Pillar p ON c.datasetId=p.datasetId AND c.pillarId=p.id WHERE c.datasetId IS NOT NULL AND c.pillarId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'changeProjectV2' AS ruleName,COUNT(*) AS violations FROM LocalChange c LEFT JOIN Project p ON c.datasetId=p.datasetId AND c.projectId=p.id WHERE c.datasetId IS NOT NULL AND c.projectId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'changeObjectiveV2' AS ruleName,COUNT(*) AS violations FROM LocalChange c LEFT JOIN Objective p ON c.datasetId=p.datasetId AND c.objectiveId=p.id WHERE c.datasetId IS NOT NULL AND c.objectiveId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'LocalChange.changeState' AS ruleName,COUNT(*) AS violations FROM LocalChange WHERE NOT (acknowledgmentState = 'pending');
SELECT 'LocalChange.changeTargetV2' AS ruleName,COUNT(*) AS violations FROM LocalChange WHERE NOT ((taskId IS NOT NULL) + (pillarId IS NOT NULL) + (projectId IS NOT NULL) + (objectiveId IS NOT NULL) = 1);
SELECT 'LocalChange.changePayloadV2' AS ruleName,COUNT(*) AS violations FROM LocalChange WHERE NOT ((payloadVersion = 1 AND taskId IS NOT NULL OR payloadVersion = 2) AND localRevision > 0 AND JSON_VALID(immutablePayload));
SELECT 'MigrationAttempt.attemptVersion' AS ruleName,COUNT(*) AS violations FROM MigrationAttempt WHERE NOT (version >= 2);
SELECT 'MigrationAttempt.attemptStep' AS ruleName,COUNT(*) AS violations FROM MigrationAttempt WHERE NOT (lastCompletedStep >= 1);
SELECT 'MigrationAttempt.attemptStateValue' AS ruleName,COUNT(*) AS violations FROM MigrationAttempt WHERE NOT (attemptState IN ('running', 'failed', 'completed'));
SELECT 'MigrationAttempt.attemptTimes' AS ruleName,COUNT(*) AS violations FROM MigrationAttempt WHERE NOT (startedAt > 0 AND ((attemptState = 'completed' AND completedAt IS NOT NULL AND completedAt >= startedAt) OR (attemptState IN ('running', 'failed') AND completedAt IS NULL)));
SELECT 'pillarDataset' AS ruleName,COUNT(*) AS violations FROM Pillar c LEFT JOIN Dataset p ON c.datasetId=p.id WHERE c.datasetId IS NOT NULL AND p.id IS NULL;
SELECT 'pillarParentScope' AS ruleName,COUNT(*) AS violations FROM Pillar c LEFT JOIN Pillar p ON c.datasetId=p.datasetId AND c.parentPillarId=p.id WHERE c.datasetId IS NOT NULL AND c.parentPillarId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'Pillar.pillarIdFormat' AS ruleName,COUNT(*) AS violations FROM Pillar WHERE NOT (id REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
SELECT 'Pillar.pillarName' AS ruleName,COUNT(*) AS violations FROM Pillar WHERE NOT (OCTET_LENGTH(name) BETWEEN 1 AND 1024 AND CHAR_LENGTH(TRIM(name)) > 0);
SELECT 'Pillar.pillarDescription' AS ruleName,COUNT(*) AS violations FROM Pillar WHERE NOT (description IS NULL OR OCTET_LENGTH(description) <= 65535);
SELECT 'Pillar.pillarNotSelf' AS ruleName,COUNT(*) AS violations FROM Pillar WHERE NOT (parentPillarId IS NULL OR parentPillarId <> id);
SELECT 'Pillar.pillarTimes' AS ruleName,COUNT(*) AS violations FROM Pillar WHERE NOT (createdAt > 0 AND updatedAt >= createdAt AND (archivedAt IS NULL OR archivedAt BETWEEN createdAt AND updatedAt) AND (deletedAt IS NULL OR deletedAt BETWEEN createdAt AND updatedAt));
SELECT 'Pillar.pillarRevision' AS ruleName,COUNT(*) AS violations FROM Pillar WHERE NOT (localRevision > 0);
SELECT 'projectDataset' AS ruleName,COUNT(*) AS violations FROM Project c LEFT JOIN Dataset p ON c.datasetId=p.id WHERE c.datasetId IS NOT NULL AND p.id IS NULL;
SELECT 'projectPillarScope' AS ruleName,COUNT(*) AS violations FROM Project c LEFT JOIN Pillar p ON c.datasetId=p.datasetId AND c.pillarId=p.id WHERE c.datasetId IS NOT NULL AND c.pillarId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'projectParentScope' AS ruleName,COUNT(*) AS violations FROM Project c LEFT JOIN Project p ON c.datasetId=p.datasetId AND c.parentProjectId=p.id WHERE c.datasetId IS NOT NULL AND c.parentProjectId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'Project.projectParentChoice' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT ((pillarId IS NOT NULL) + (parentProjectId IS NOT NULL) = 1);
SELECT 'Project.projectNotSelf' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT (parentProjectId IS NULL OR parentProjectId <> id);
SELECT 'Project.projectIdFormat' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT (id REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
SELECT 'Project.projectTitle' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT (OCTET_LENGTH(title) BETWEEN 1 AND 1024 AND CHAR_LENGTH(TRIM(title)) > 0);
SELECT 'Project.projectDescription' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT (description IS NULL OR OCTET_LENGTH(description) <= 65535);
SELECT 'Project.projectTimes' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT (createdAt > 0 AND updatedAt >= createdAt AND (archivedAt IS NULL OR archivedAt BETWEEN createdAt AND updatedAt) AND (deletedAt IS NULL OR deletedAt BETWEEN createdAt AND updatedAt));
SELECT 'Project.projectRevision' AS ruleName,COUNT(*) AS violations FROM Project WHERE NOT (localRevision > 0);
SELECT 'objectiveDataset' AS ruleName,COUNT(*) AS violations FROM Objective c LEFT JOIN Dataset p ON c.datasetId=p.id WHERE c.datasetId IS NOT NULL AND p.id IS NULL;
SELECT 'objectivePillarScope' AS ruleName,COUNT(*) AS violations FROM Objective c LEFT JOIN Pillar p ON c.datasetId=p.datasetId AND c.pillarId=p.id WHERE c.datasetId IS NOT NULL AND c.pillarId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'objectiveProjectScope' AS ruleName,COUNT(*) AS violations FROM Objective c LEFT JOIN Project p ON c.datasetId=p.datasetId AND c.projectId=p.id WHERE c.datasetId IS NOT NULL AND c.projectId IS NOT NULL AND p.datasetId IS NULL;
SELECT 'Objective.objectiveParentChoice' AS ruleName,COUNT(*) AS violations FROM Objective WHERE NOT ((pillarId IS NOT NULL) + (projectId IS NOT NULL) = 1);
SELECT 'Objective.objectiveIdFormat' AS ruleName,COUNT(*) AS violations FROM Objective WHERE NOT (id REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
SELECT 'Objective.objectiveTitle' AS ruleName,COUNT(*) AS violations FROM Objective WHERE NOT (OCTET_LENGTH(title) BETWEEN 1 AND 1024 AND CHAR_LENGTH(TRIM(title)) > 0);
SELECT 'Objective.objectiveDescription' AS ruleName,COUNT(*) AS violations FROM Objective WHERE NOT (description IS NULL OR OCTET_LENGTH(description) <= 65535);
SELECT 'Objective.objectiveTimes' AS ruleName,COUNT(*) AS violations FROM Objective WHERE NOT (createdAt > 0 AND updatedAt >= createdAt AND (archivedAt IS NULL OR archivedAt BETWEEN createdAt AND updatedAt) AND (deletedAt IS NULL OR deletedAt BETWEEN createdAt AND updatedAt));
SELECT 'Objective.objectiveRevision' AS ruleName,COUNT(*) AS violations FROM Objective WHERE NOT (localRevision > 0);
